<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>The State of Global Education - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body {
      width: 794px;
      height: 1123px;
      background: #0f1b2d;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    #container {
      width: 794px;
      height: 1123px;
    }
  </style>
</head>
<body>
  <div id="container"></div>
  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    const syntax = `infographic list-waterfall-compact-card
data
  title The State of Global Education
  desc Progress, Gaps & Inequality — A Two-Century Story
  lists
    - label TWO CENTURIES OF PROGRESS
      value 80
      desc Adults with basic education today: > 4 in 5. In 1800: fewer than 1 in 5. Humanity reversed the odds.
      icon academic cap
    - label 244 MILLION CHILDREN OUT OF SCHOOL
      value 244
      desc 244 million children of school age were not enrolled in 2023. 184M are secondary-age dropouts; 60M are primary-age.
      icon user group
    - label THE LEARNING CRISIS
      value 20
      desc In low-income countries, fewer than 20% of children reach minimum reading proficiency by end of primary school.
      icon book open
    - label A WORLD DIVIDED IN QUALITY
      value 3
      desc Poorest nations: < 3 years of quality schooling. High-income countries: 10+ years. A 3× gap in learning outcomes.
      icon chart bar
    - label CLOSING THE GENDER GAP
      value 50
      desc Globally, the gender gap in primary and secondary enrollment has nearly closed. Women now outnumber men in tertiary education.
      icon heart
theme
  palette #1e3a5f #e67e22 #e74c3c #f1c40f #27ae60`;

    const infographic = new AntVInfographic.Infographic({
      container: '#container',
      width: '100%',
      height: '100%',
    });

    infographic.render(syntax);

    document.fonts?.ready.then(() => {
      infographic.render(syntax);
    }).catch((error) => console.error('Error waiting for fonts:', error));
  </script>
</body>
</html>
