[metadata] {"type": "update", "filePath": "/app/output/global-education-infographic.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>The State of Global Education - Infographic</title>
  <style>
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;900&display=swap');

    * { margin: 0; padding: 0; box-sizing: border-box; }

    html, body {
      width: 794px;
      height: 1123px;
      background: #0b1829;
      font-family: 'Inter', 'Segoe UI', Arial, sans-serif;
      color: #e8edf5;
      overflow: hidden;
    }

    .poster {
      width: 794px;
      height: 1123px;
      background: linear-gradient(175deg, #0d1f35 0%, #0b1829 60%, #0a1520 100%);
      display: flex;
      flex-direction: column;
      padding: 36px 44px 28px;
      gap: 0;
    }

    /* ── HEADER ── */
    .header {
      text-align: center;
      margin-bottom: 18px;
    }
    .header-eyebrow {
      font-size: 10px;
      font-weight: 600;
      letter-spacing: 3px;
      text-transform: uppercase;
      color: #e67e22;
      margin-bottom: 6px;
    }
    .header-title {
      font-size: 26px;
      font-weight: 900;
      color: #ffffff;
      line-height: 1.15;
      letter-spacing: -0.5px;
      margin-bottom: 8px;
    }
    .header-title span { color: #e67e22; }
    .header-subtitle {
      font-size: 11.5px;
      color: #8fa8c8;
      font-weight: 400;
      letter-spacing: 0.3px;
    }

    /* ── DIVIDER ── */
    .divider {
      height: 1px;
      background: linear-gradient(90deg, transparent, #1e3a5f, #e67e22, #1e3a5f, transparent);
      margin-bottom: 16px;
    }

    /* ── PROGRESS HERO ── */
    .progress-hero {
      background: linear-gradient(135deg, #112240 0%, #1a3a6e 100%);
      border: 1px solid #1e3f72;
      border-radius: 12px;
      padding: 18px 24px;
      margin-bottom: 14px;
      display: flex;
      align-items: center;
      gap: 24px;
    }
    .progress-hero-label {
      font-size: 9.5px;
      font-weight: 700;
      letter-spacing: 2.5px;
      text-transform: uppercase;
      color: #e67e22;
      margin-bottom: 6px;
    }
    .progress-hero-title {
      font-size: 14px;
      font-weight: 700;
      color: #cdd9ea;
      margin-bottom: 14px;
    }
    .progress-bars {
      display: flex;
      flex-direction: column;
      gap: 8px;
      flex: 1;
    }
    .bar-row {
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .bar-year {
      font-size: 10px;
      font-weight: 700;
